DROP DATABASE IF EXISTS sql_data_analyst_practice;              -----  DAY 1 -----
CREATE DATABASE sql_data_analyst_practice;
USE sql_data_analyst_practice;

CREATE TABLE employee_sales (
 employee_id INT PRIMARY KEY,
 employee_name VARCHAR(50) NOT NULL,
 department VARCHAR(30),
 job_title VARCHAR(50),
 manager_id INT NULL,
 city VARCHAR(30),
 salary DECIMAL(10,2),
 sales_amount DECIMAL(12,2),
 joining_date DATE,
 email VARCHAR(100),
 status VARCHAR(20),
 bonus DECIMAL(10,2) NULL
);

